#!/usr/bin/env python3
"""Admit only the source-bound normal scalar SBP pair after every CPU gate passes."""
import argparse,hashlib,json
from pathlib import Path

def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def main():
 p=argparse.ArgumentParser();p.add_argument('--evidence',type=Path,required=True);p.add_argument('--review',type=Path,required=True);p.add_argument('--output',type=Path,required=True);p.add_argument('--damping',type=float,choices=[0,2],default=2);p.add_argument('--backend-review',type=Path,action='append',default=[]);p.add_argument('--additional-audit',type=Path,action='append',default=[]);a=p.parse_args()
 if a.output.exists():raise RuntimeError('Existing admission is immutable')
 E=a.evidence;matrix=json.loads(a.review.read_text());runs=[Path(d) for d in matrix['runs']];times=[Path(d) for d in matrix['time_runs']];outer=[Path(d) for d in matrix['outer_runs']];ns=matrix['resolutions']
 if len(times)!=3 or len(outer)!=2:raise RuntimeError('Completed controls must be specified explicitly')
 expected=dict(M=0,a_over_M=0,L=3,S=24,C=10,cap=1,cfl=.18,ko=0,reduction_damping=a.damping,radial_stretch=-2,outer_sbp=2,smooth_physical_layer=True,reference_layer='original_quintic',normal_upwind=True,compatible_reduction=False,characteristic_transfer=False,excision=0,tlim=12,boundary='exact',data='angular');cases=[(d,n,{}) for d,n in zip(runs,ns)]+[(d,ns[1],dict(cfl=cfl)) for d,cfl in zip(times[1:],[.09,.045])]+[(d,ns[-1],dict(cap=cap,boundary='radiation')) for d,cap in zip(outer,[.9,.95])];settings=[];frozen=[];nominal=json.loads((runs[1]/'frozen-integrity.json').read_text());keys=['physical_before','reference_before','physical_derivatives_before','reference_derivatives_before']
 for d,n,override in cases:
  actual=json.loads((d/'parameters.json').read_text());target={**expected,'n':n,**override};mismatch={k:dict(expected=v,actual=actual.get(k)) for k,v in target.items() if actual.get(k)!=v};g=json.loads((d/'frozen-integrity.json').read_text());same=all(g[k]==nominal[k] for k in keys) if n==ns[1] else True;settings.append(dict(run=str(d),mismatches=mismatch,passed=not mismatch));frozen.append(dict(run=str(d),unchanged=g['unchanged'],time_coefficients_identical=same,passed=g['unchanged'] and same))
 names=['geometry-smooth/review.json','geometry-normal/derivative-review.json','geometry-normal/normal-source-review.json','geometry-difference/review.json','normal-upwind-sbp-algebra.json','cpu-v20/compiled-operator-review.json','cpu-v20/unchanged-background-review.json',('cpu-v21/undamped-long-minkowski-review.json' if a.damping==0 else 'cpu-v20/long-minkowski-review.json'),'cpu-v21/halo-equivalence-review.json','cpu-v18/inner-guard-review.json','cpu-v18/wall-time-checkpoint-review.json']
 names.append('geometry-normal/full-3d-source-review.json')
 if a.damping==0:names.append('cpu-v21/actual-time-derivative-review.json')
 audits=[dict(path=name,sha256=sha(E/name),passed=json.loads((E/name).read_text())['passed']) for name in names]
 backends=[json.loads(path.read_text()) for path in a.backend_review];audits += [dict(path=str(path),sha256=sha(path),passed=record['passed']) for path,record in zip(a.backend_review,backends)]
 audits += [dict(path=str(path),sha256=sha(path),passed=json.loads(path.read_text())['passed']) for path in a.additional_audit]
 allowed_external={record['validated_binary_sha256'] for record in backends if record['passed']};unvalidated_external=[str(d) for d,n,o in cases if json.loads((d/'invocation.json').read_text())['binary'] not in [sha(E/'cpu-v20/test_scalar'),sha(E/'cpu-v21/test_scalar'),*allowed_external]]
 baseline=json.loads((E/'frozen-baseline-sha256.json').read_text());mismatch=[name for name,digest in baseline.items() if not Path(name).is_file() or sha(Path(name))!=digest];project=Path(__file__).resolve().parents[2];source={name:sha(E/'cpu-v21/source'/name) for name in ['CMakeLists.txt','main.cpp','geometry.hpp','sbp63.hpp']};source_matches=all(sha(project/'src/test_scalar'/name)==digest for name,digest in source.items());dependencies={name:sha(project/name) for name in ['src/athena.hpp','src/mesh/cubed_sphere/map.hpp']}
 numerical=['--normal-upwind','1','--outer-sbp','2','--ko','0','--reduction-damping',str(a.damping),'--smooth-layer','1','--radial-stretch','-2','--cfl','.18'];gpu_cases=[dict(n=n,arguments=['--n',str(n),'--tlim','12','--mass','0','--spin','0','--cap','1','--excision','0','--boundary','exact','--data','angular',*numerical]) for n in ns]
 passed=matrix['passed'] and matrix['complete'] and source_matches and not mismatch and all(c['passed'] for c in settings+frozen+audits) and all(c['passed'] for c in matrix['checks']) and not unvalidated_external
 result=dict(stage='minkowski',configuration='normal-upwind-sbp63',reduction_damping=a.damping,passed=passed,complete=matrix['complete'],resolutions=ns,matrix_review=str(a.review),matrix_sha256=sha(a.review),settings=settings,frozen=frozen,audits=audits,baseline_files=len(baseline),baseline_mismatches=mismatch,delivery_source_matches=source_matches,delivery_source_sha256=source,dependency_source_sha256=dependencies,unvalidated_external_runs=unvalidated_external,cpu_binary_sha256=sha(E/('cpu-v21/test_scalar' if a.damping==0 else 'cpu-v20/test_scalar')),equivalent_delivery_binary_sha256=sha(E/'cpu-v21/test_scalar'),numerical_arguments=numerical,gpu_cases=gpu_cases,qualification='Three-resolution analytic field/velocity reconstruction/spatial derivative/reduction checks through t12, timestep and finite-cap controls, plus coarse t100 stability control. Independent radial SBP algebra is not a full multipatch energy proof. No Schwarzschild/Kerr or metric-evolution admission.')
 a.output.write_text(json.dumps(result,indent=2)+'\n');print(json.dumps(dict(passed=passed,settings_passed=all(c['passed'] for c in settings),audits_passed=all(c['passed'] for c in audits),source_matches=source_matches,baseline_mismatches=mismatch),indent=2))
 if not passed:raise SystemExit(1)
if __name__=='__main__':main()
